/** Shown when this mix is being generated by another tab of this browser, or likely another device. */
import { MonitorSmartphone } from 'lucide-react'
import { Button } from '@/components/ui'

export function ElsewhereNotice({ where, onContinueHere }: { where: 'tab' | 'device'; onContinueHere: () => void }) {
  return (
    <div className="flex flex-col gap-3 rounded-xl border border-border bg-card/60 p-4 text-sm sm:flex-row sm:items-center" data-testid="mix-elsewhere">
      <MonitorSmartphone aria-hidden className="size-5 shrink-0 text-primary" />
      <p className="flex-1 text-muted-foreground">
        {where === 'tab' ? (
          <>This mix is being created in <span className="text-foreground">another tab of this browser</span>. Progress here updates live; this tab takes over automatically if that one closes.</>
        ) : (
          <>This mix looks like it's being created in <span className="text-foreground">another tab or on another device</span>. Progress here updates live.</>
        )}
      </p>
      {where === 'device' && (
        <Button variant="outline" size="sm" onClick={onContinueHere} data-testid="mix-continue-here">
          Continue here instead
        </Button>
      )}
    </div>
  )
}
